from dataclasses import dataclass

@dataclass
class TruckState:
    truck_id: str
    temp_c: float            # latest cargo reading
    limit_c: float           # product limit, e.g. 5.0 for chilled
    slope_c_per_hr: float    # trend over the last 30 minutes
    hours_to_arrival: float
    sensor_age_min: float

def breach_risk(s: TruckState) -> tuple[str, str]:
    """Return (level, reason). Rules first; a model can replace this later."""
    if s.sensor_age_min > 45:
        return "UNKNOWN", f"no reading for {s.sensor_age_min:.0f} min"
    if s.temp_c >= s.limit_c:
        return "BREACH", f"{s.temp_c:.1f} C is over the {s.limit_c:.1f} C limit"
    if s.slope_c_per_hr > 0:
        hours_to_limit = (s.limit_c - s.temp_c) / s.slope_c_per_hr
        if hours_to_limit < s.hours_to_arrival:
            return "AT_RISK", f"reaches limit in {hours_to_limit:.1f} h, arrival in {s.hours_to_arrival:.1f} h"
    return "OK", "stable"
